var S, desiredPt;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("visualization of a blended animation between archimedes circle and a line lerping to the endpoint");

  noFill();
	stroke("silver");
	S = max(width, height);

	desiredPt = getDesiredPt();

  loop();
}

function draw() {
	if (frameCount % 1200 === 0) {
		background("rgb(2, 2, 8)");
		desiredPt = getDesiredPt();
	}

	translate(width/2, height/2);
	rotate(fract(desiredPt.x+desiredPt.y)-0.5);

	strokeWeight(2);
	stroke("purple");
	const t = constrain((frameCount % 1200) / 1000, 0, 1); // 0..1
	const p1 = drawArch(t);
	const p2 = drawLine(t);
	stroke("cyan")
	strokeWeight(4);
	drawPt(p1, p2, t);
}

function getDesiredPt() {
	const x = random(width); // width/2, 
	const y = random(height); // height/3
	return {x, y};
}

function drawArch(t) {
	const r = map(t, 0, 1, 0, max(width, height)/2)
	const a = map(t, 0, 1, 0, 5 * TWO_PI);
	var x = cos(a) * r;
	var y = sin(a) * r;
	const p = {x, y};
	point(p.x, p.y);
	return p;
}

function drawLine(t) {
	var p1 = {x: 0, y: 0};
	var p2 = desiredPt; // {x: width/2, y: height/3};
	t = t*t*t*t;
	var p = {x: lerp(p1.x, p2.x, t), y: lerp(p1.y, p2.y, t)}
	point(p.x, p.y);
	return p;
}

function drawPt(p1, p2, t) {
	t = t*t*t*t;
	var p = {x: lerp(p1.x, p2.x, t), y: lerp(p1.y, p2.y, t)}
	point(p.x, p.y);
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
